let language='zh';try{const saved=localStorage.getItem('site-language');if(messages[saved])language=saved;}catch{}
let currentProject=null;
const menuButton=document.querySelector('#menu-toggle'),menu=document.querySelector('#more-menu'),languageButton=document.querySelector('#language-toggle'),languageMenu=document.querySelector('#language-menu');
function t(key){return messages[language][key];}
function updateMenuLabel(){menuButton.setAttribute('aria-label',t(menu.hidden?'openMenu':'closeMenu'));}
function closeMenus(){menu.hidden=true;languageMenu.hidden=true;menuButton.setAttribute('aria-expanded','false');languageButton.setAttribute('aria-expanded','false');updateMenuLabel();}
function applyLanguage(next){
language=next;document.documentElement.lang=t('lang');document.title=t('pageTitle');document.querySelector('meta[name=description]').content=t('pageTitle');
document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n);});document.querySelectorAll('[data-i18n-aria]').forEach(el=>el.setAttribute('aria-label',t(el.dataset.i18nAria)));
document.querySelector('#current-language').textContent=t('name');menu.setAttribute('aria-label',t('navigation'));languageButton.setAttribute('aria-label',t('chooseLanguage'));languageMenu.setAttribute('aria-label',t('chooseLanguage'));document.querySelector('.cinema-hero').setAttribute('aria-label',t('wall'));updateMenuLabel();
document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===language)));
document.querySelectorAll('[data-film-title]').forEach(el=>{el.textContent=t('filmTitles')[el.dataset.filmTitle]||el.dataset.filmTitle;});document.querySelectorAll('.credit-thumbs a').forEach(el=>{el.setAttribute('aria-label',t('sourceLink')+': '+(t('filmTitles')[el.dataset.film]||el.dataset.film));el.title=el.getAttribute('aria-label');});
if(currentProject!==null)renderProject(currentProject);document.dispatchEvent(new Event('localechange'));try{localStorage.setItem('site-language',language);}catch{}
}
menuButton.addEventListener('click',()=>{const shouldOpen=menu.hidden;closeMenus();menu.hidden=!shouldOpen;menuButton.setAttribute('aria-expanded',String(shouldOpen));updateMenuLabel();if(shouldOpen)menu.querySelector('button').focus();});
languageButton.addEventListener('click',()=>{const shouldOpen=languageMenu.hidden;closeMenus();languageMenu.hidden=!shouldOpen;languageButton.setAttribute('aria-expanded',String(shouldOpen));if(shouldOpen)languageMenu.querySelector('[aria-pressed=true]').focus();});
document.querySelectorAll('[data-language]').forEach(b=>b.addEventListener('click',()=>{applyLanguage(b.dataset.language);closeMenus();languageButton.focus();}));
document.addEventListener('click',event=>{if(!event.target.closest('.menu-wrap,.language-wrap'))closeMenus();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&(!menu.hidden||!languageMenu.hidden)){const origin=!menu.hidden?menuButton:languageButton;closeMenus();origin.focus();}});
for(const panel of [menu,languageMenu])panel.addEventListener('keydown',event=>{const buttons=[...panel.querySelectorAll('button')];const index=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();}});
document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>{closeMenus();if(button.dataset.action==='home'){document.querySelector('#home').scrollIntoView();menuButton.focus();}else document.querySelector('#'+button.dataset.action+'-dialog').showModal();}));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});});
const projectImages=['photo-1464822759023-fed622ff2c3b','photo-1518837695005-2083093ee35b','photo-1447752875215-b2761acb3c5d'];
function renderProject(index){document.querySelector('#detail-title').textContent=t('project'+index);document.querySelector('#detail-text').textContent=t('descriptions')[index];const img=document.querySelector('.project-image');img.src='https://images.unsplash.com/'+projectImages[index]+'?auto=format&fit=crop&w=1000&q=85';img.alt=t('project'+index);}
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{currentProject=Number(button.dataset.project);renderProject(currentProject);document.querySelector('#project-detail').showModal();}));
applyLanguage(language);

